                        let cD = 0, cE = 0, cM = 0, cS = 0, cA = 0, cR = 0;
                        let topScore = 0;
                        let destinyRounds = [];

                        for (let i = 0; i < rounds.length; i++) {
                            let r = rounds[i];
                            if (r.loveScore > topScore) topScore = r.loveScore;
                            if (r.loveScore <= 20) cD++;
                            else if (r.loveScore <= 40) cE++;
                            else if (r.loveScore <= 60) cM++;
                            else if (r.loveScore <= 80) cS++;
                            else if (r.loveScore <= 98) cA++;
                            else cR++;

                            if (r.isDestiny) {
                                destinyRounds.push({
                                    round: i + 1,
                                    titleName: r.titleName,
                                    loveScore: r.loveScore,
                                    afterSuccess: r.afterSuccess
                                });
                            }
                        }

                        let remaining = (data.member[sender].bag && data.member[sender].bag[datingItemName]) || 0;
                        let totalJackpot = destinyCount * 10000000000;

                        let resultMsg = "💘 호이월드 소개팅 💘\n";
                        resultMsg += "[" + checkRank(data, petData, guildData, sender) + "] 님 (" + openCount + "회 진행)" + allsee + "\n\n";

