                    let miniPetBattleMax = GLOBAL_CONFIG.daily.miniPetBattleMax + (autoDailyQuestInternalDepth > 0 ? GLOBAL_CONFIG.daily.autoDailyBonusRuns : 0); // 자동일퀘 추가 보상을 포함한 최대 대전 횟수
                    // 미니펫 장착 확인
