                    replier.reply("✅ [" + targetGrade + "] 등급 이하 정리 완료!\n" + "정리 수: " + soldCount + "개\n\n" + "🅟" + numberWithCommas(earnedPoint) + " 획득");

                    saveJsonFile(petData, memberPetPath);
                    saveJsonFile(data, filePath);
