                    var c50 = 0,
                        c100 = 0,
                        c250 = 0,
                        c500 = 0;

                    for (var i = 0; i < openCount; i++) {
                        var r1 = rollPetFoodBoxRandom();
                        var cnt = r1.gainItems["펫먹이🍼"];
                        totalFood += cnt;

                        if (cnt === 50) c50++;
                        else if (cnt === 100) c100++;
                        else if (cnt === 250) c250++;
                        else if (cnt === 500) c500++;
                    }

                    // 먹이 지급
                    addItem(data, sender, "펫먹이🍼", totalFood);

                    // 출력(UI)
                    var remain = data.member && data.member[sender] && data.member[sender].bag && data.member[sender].bag[boxName] ? data.member[sender].bag[boxName] : 0;

                    var out = "";
                    out += "📦 펫먹이상자 오픈!\n";
                    out += "━━━━━━━━━━━━\n";
                    out += "오픈 개수: " + openCount + "개 (잔여: " + remain + "개)\n";
