                    for (var i = 0; i < openCount; i++) {
                        var result = rollPetFoodSpecialRandom();

                        for (var it in result.gainItems) {
                            var cnt = result.gainItems[it];

                            addItem(data, sender, it, cnt);

                            if (!summary[it]) summary[it] = 0;
                            summary[it] += cnt;

                            if (it === "펫먹이🍼") totalFood += cnt;
                        }
                    }

                    var remain = data.member[sender].bag[itemName] || 0;

                    // 출력
                    var out = "";
                    out += "🥡 펫먹이특식 오픈!\n";
                    out += "━━━━━━━━━━━━\n";
