// 길드 최대 정원을 계산하여 반환 (길드 레벨 기본 정원 + 징집명령📙 보정)
function getGuildMaxMemberLimit(g, petSkillData) {
    var maxMember = g ? (g.maxMember || 5) : 0;
    if (g && hasPetSkill(petSkillData, g.master, "징집명령")) {
        maxMember += 1;
    }
    return maxMember;
}

// 창조 미니펫 장착 여부 확인 함수
function hasEquippedCreationMiniPet(petData, user) {
    return !!(petData &&
        petData[user] &&
        petData[user].miniPet &&
        (petData[user].miniPet.grade || "") === "창조");
}

// 길드의 소드마스터 수 계산 및 보장
function getGuildTerritoryAttackLimit(g, petSkillData) {
    var swordMasters = ensureGuildSwordMasters(g, petSkillData);
    var limit = Math.max(1, swordMasters.length) * GLOBAL_CONFIG.guildTerritory.limits.attackCountPerSwordMaster;
    if (hasGuildTerritoryCommanderSkill(g, petSkillData, g && g.master)) {
        limit += 5;
    }
    return limit;
}

// 길드 영지전 공격 제한 계산 (길드별 설정이 있으면 우선, 없으면 소드마스터 수 기반)
function getGuildTerritoryAttackLimitForWar(war, g, guildId) {
    if (war && war.guildAttackLimits && typeof war.guildAttackLimits[guildId] === "number") {
        return war.guildAttackLimits[guildId];
    }
    return getGuildTerritoryAttackLimit(g, null);
}

// 길드 영지전 개인 공격 횟수 반환
function getGuildTerritoryUserAttackCount(war, user) {
    if (!war.userAttackCounts || typeof war.userAttackCounts !== "object") war.userAttackCounts = {};
    return war.userAttackCounts[user] || 0;
}

// 길드 영지전 개인 공격 횟수 1회 증가
function increaseGuildTerritoryUserAttackCount(war, user) {
    if (!war.userAttackCounts || typeof war.userAttackCounts !== "object") war.userAttackCounts = {};
    war.userAttackCounts[user] = (war.userAttackCounts[user] || 0) + 1;
    return war.userAttackCounts[user];
}

// 길드 영지전 균열 이벤트 발생 횟수 계산 및 보장
function getGuildTerritoryRiftEventCount(war) {
    return Math.max(0, Math.min(GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount, (war && war.riftEventCount) || 0));
}

// 길드 영지전 균열 이벤트 발생 횟수 한도 도달 여부 확인
function isGuildTerritoryRiftEventLimitReached(war) {
    return getGuildTerritoryRiftEventCount(war) >= GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount;
}

// 길드 영지전 균열 이벤트 발생 횟수 및 남은 횟수 텍스트 빌드
function buildGuildTerritoryRiftEventLimitText(war) {
    var count = getGuildTerritoryRiftEventCount(war);
    var remain = Math.max(0, GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount - count);
    if (remain <= 0) {
        return "※ 균열 이벤트 발생 횟수: (" + count + "/" + GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount + ")\n※ 이번 영지전에서는 더 이상 균열 이벤트가 발생하지 않습니다.";
    }
    return "※ 균열 이벤트 발생 횟수: (" + count + "/" + GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount + ")\n※ 이번 영지전에서는 균열 이벤트가 " + remain + "회 더 발생할 수 있습니다.";
}

// 길드 영지전 균열 이벤트 발생 시 상태 업데이트 및 안내 텍스트 빌드
function markGuildTerritoryRiftEvent(war, status, guildId) {
    war.riftEventCount = getGuildTerritoryRiftEventCount(war) + 1;
    if (!Array.isArray(war.riftEventHistory)) war.riftEventHistory = [];
    war.riftEventHistory.push(status);
    war.riftEventStatus = status;
    war.riftEventAt = formatDateTime(new Date());
    war.riftEventGuildId = guildId || null;
    return buildGuildTerritoryRiftEventLimitText(war);
}

// 길드 영지전 균열 이벤트 히스토리 가져오기 (최대 GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount개까지)
function getGuildTerritoryRiftEventHistory(war) {
    if (!war) return [];
    if (Array.isArray(war.riftEventHistory)) return war.riftEventHistory.slice(0, GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount);
    if (getGuildTerritoryRiftEventCount(war) > 0 && (war.riftEventStatus === "rift" || war.riftEventStatus === "greatRift")) return [war.riftEventStatus];
    return [];
}

// 길드 영지전 균열 이벤트 상태 초기화
function resetGuildTerritoryInstability(war) {
    if (!war) return;
    war.turnCount = 0;
    war.instabilityAdjust = 0;
}

// 길드 영지전 균열 이벤트 슬롯 텍스트 포맷 함수
function formatGuildTerritoryRiftEventSlot(status, index, occurrenceCount, locked) {
    var prefix = index === 0 ? "└" : "  └";
    var countText = occurrenceCount + "회";
    var lockText = locked ? "💥" : "";
    if (status === "rift") return prefix + "[🌌균열 " + countText + " 발생" + lockText + "]";
    if (status === "greatRift") return prefix + "[🌋대균열 " + countText + " 발생" + lockText + "]";
    return prefix + "[🌌미발생" + lockText + "]";
}

//	영지전 불안정도 기본 증가율 계산 
function getGuildTerritoryInstabilityBaseRate(turnCount) {
    var turn = Math.max(1, Math.min(GLOBAL_CONFIG.guildTerritory.limits.riftMaxTurn, turnCount || 1));
    return turn / 20;
}

// 영지전 불안정도 계산 (턴 수 기반 + 조정치, 균열 한도 도달이거나 턴 수 초과 시 0%)
function getGuildTerritoryInstabilityRate(war) {
    if (!war || war.riftEventStatus === "stable" || isGuildTerritoryRiftEventLimitReached(war)) return 0;
    if ((war.turnCount || 0) > GLOBAL_CONFIG.guildTerritory.limits.riftMaxTurn) return 0;
    var turn = war.turnCount || 0;
    var rate = (turn > 0 ? getGuildTerritoryInstabilityBaseRate(turn) : 0) + (war.instabilityAdjust || 0);
    return Math.max(0, Math.min(20, rate));
}

// 균열 발생 확률 계산 (리프트 편향 적용)
function getGuildTerritoryRiftRates(war) {
    var riftRate = Math.max(0, Math.min(100, GLOBAL_CONFIG.guildTerritory.rates.riftBaseRate + (war.riftBias || 0)));
    return {
        rift: riftRate,
        greatRift: 100 - riftRate
    };
}

// 퍼센트 포맷 함수 (소수점 1자리까지)
function formatPercent1(value) {
    return (Math.round((value || 0) * 10) / 10).toFixed(1);
}

// 영지전 균열 이벤트 UI 빌드
function buildGuildTerritoryRiftUi(war) {
    if (!war) return "";
    if (war.riftEventStatus === "stable") return "[🌪️ 누적 전쟁불안정도: 0]\n└[전장 안정화🔒]";

    var instability = getGuildTerritoryInstabilityRate(war);
    var history = getGuildTerritoryRiftEventHistory(war);
    var locked = isGuildTerritoryRiftEventLimitReached(war);
    var eventCounts = { rift: 0, greatRift: 0 };
    var out = "[🌪️ 누적 전쟁불안정도: " + formatPercent1(instability) + "%]";
    for (var i = 0; i < GLOBAL_CONFIG.guildTerritory.limits.riftMaxEventCount; i++) {
        var status = history[i];
        if (status === "rift" || status === "greatRift") eventCounts[status]++;
        out += "\n" + formatGuildTerritoryRiftEventSlot(status, i, eventCounts[status] || 0, locked);
    }
    if (locked) out += "\n     └[🌌🌋균열발생 종료🔒]";
    return out;
}

function getGuildTerritoryTimeoutMissCount(war, guildId) {
    if (!war || !war.timeoutMissCounts || !guildId) return 0;
    return war.timeoutMissCounts[guildId] || 0;
}

// 영지전 상황 메시지 빌드
function buildGuildTerritoryStatusMessage(data, guildData, includeCommand) {
    var war = ensureGuildTerritoryWar(data, guildData);
    var list = getGuildTerritoryList();
    var out = "🎖️현재 길드 영지전 상황🎖️\n━━━━━━━━━━━━\n";

    for (var i = 0; i < list.length; i++) {
        var ter = war.territories[String(list[i].no)];
        var g = getGuildByIdSafe(guildData, ter ? ter.ownerGuildId : null);
        out += "[" + list[i].no + "] " + list[i].name + ": " + formatGuildDisplay(g) + "\n";
    }
    out += "━━━━━━━━━━━━\n";
    out += "[8] 차원의 문 🌀: " + (war.dimensionGateEnabled ? "환생 하고싶누?\n(20% 확률 4턴 증가 80% 확률 탈락 -2턴 차감)" : "닫힘(OFF)") + "\n";
    out += "[9] 날 기억해줘😭: " + (war.rememberMeEnabled ? "주인공 되고싶누?\n(30% 확률 점령지 1곳 미점령, 공격 1턴 소모)" : "닫힘(OFF)") + "\n";
    if (includeCommand) out += "\n순고한 히셍 간사함니다";
    return out;
}

// 길드영지 누적 점수 순위 행을 생성하는 함수
function buildGuildTerritoryScoreRankingRows(guildData) {
    var rows = [];
    if (!guildData || !guildData.guilds) return rows;
    for (var gid in guildData.guilds) {
        if (!guildData.guilds.hasOwnProperty(gid)) continue;
        var guild = guildData.guilds[gid];
        if (!guild) continue;
        var score = ensureGuildTerritoryScore(guild);
        if (score <= 0) continue;
        rows.push({
            gid: gid,
            guild: guild,
            score: score,
            level: guild.level || 1
        });
    }
    rows.sort(function(a, b) {
        if (b.score !== a.score) return b.score - a.score;
        if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0);
        return String(a.guild.name || "").localeCompare(String(b.guild.name || ""), "ko");
    });
    return rows;
}

// 길드영지 순위에서 길드장 전체 표시명을 안전하게 반환하는 함수
function formatGuildTerritoryMasterDisplay(data, guildData, guild) {
    if (!guild || !guild.master) return "길드장 정보 없음";
    if (!data || !data.member || !data.member[guild.master]) return "길드장 정보 없음";
    return checkRank(data, null, guildData, guild.master);
}

// 길드영지 누적 점수 순위 메시지를 생성하는 함수
function buildGuildTerritoryRankingMessage(data, guildData) {
    var rows = buildGuildTerritoryScoreRankingRows(guildData);
    var out = "📈 🏅 길드영지 순위 🏅 📈\n\n";
    out += "━━━━━━━━━━━\n";
    out += "영지pt 획득 기준\n";
    out += "(추가 점수 1pt당 길드영지 부스터🔮 1개 차감)\n";
    out += "호월킹덤🏰 50pt\n";
    out += "펫스킬 광산📙 20pt\n";
    out += "펜던트 광산📿 20pt\n";
    out += "펫강화광산⭐️ 50pt\n";
    out += "미니펫강화광산💫 50pt\n";
    out += "다이아광산💎 20pt\n";
    out += "길드영지PT광산🪙 " + GLOBAL_CONFIG.guildTerritory.scores.pointMine + "pt(부스터 " + GLOBAL_CONFIG.guildTerritory.scores.pointMine + "개 적용 시 " + (GLOBAL_CONFIG.guildTerritory.scores.pointMine * 2) + "pt)\n";
    out += "━━━━━━━━━━━\n";
    if (rows.length === 0) return out + "아직 누적 영지점수가 없습니다.";

    for (var i = 0; i < rows.length; i++) {
        if (i === 3 && typeof allsee !== "undefined") {
            out += "⭐ 다른 길드 보러가기.. 👉 (4등부터~)\n" + allsee + "\n";
        }
        var guild = rows[i].guild;
        out += (i + 1) + ". " + formatGuildDisplay(guild) + "\n";
        out += "[" + (guild.server || "서버미상") + "]\n";
        out += "[" + formatGuildTerritoryMasterDisplay(data, guildData, guild) + "][Lv." + (guild.level || 1) + "]\n";
        out += "[누적 영지점수: " + numberWithCommas(rows[i].score) + "pt]\n\n";
    }

    return out.replace(/\n\n$/, "");
}

