////////////////////save Log.txt, load game.txt////////////////////////
function read(folderName, fileName) {
    //파일 읽기 함수 제작
    var b = new java.io.File(sdcard + "/" + folderName + "/" + fileName);
    if (!b.exists()) return null;
    var c = new java.io.FileInputStream(b);
    var d = new java.io.InputStreamReader(c);
    var e = new java.io.BufferedReader(d);
    var f = e.readLine();
    var g = "";
    while ((g = e.readLine()) != null) {
        f += "\n" + g; //\ = 역슬래쉬 → 줄바꿈 표시
    }
    c.close();
    d.close();
    e.close();
    return String(f);
}
////////////////////ㅊㅊ보너스내용////////////////////////
function RankBonus(data, user) {
    var Bonusmsg = "";
    var BonusM = 0;
    var tierName = data.member[user].rank.tier;
    var tierInfo = ticketTierData[tierName];
    if (!tierInfo || !tierInfo.bonusP) {
        return {
            BonusM: 0,
            Bonusmsg: ""
        };
    }
    var bonusP = tierInfo.bonusP;
    if (Math.random() < bonusP) {
        BonusM = rollAndCalculateMultiplier();
        Bonusmsg = tierInfo.emoji + "보너스 (" + Math.floor(bonusP * 100) + "%) 발동! 다시 굴리기~" + BonusM + "배 당첨!";
    }
    return {
        BonusM: BonusM,
        Bonusmsg: Bonusmsg
    };
}
// 주사위를 굴려 배율을 계산하는 외부 함수
function rollAndCalculateMultiplier() {
    // 주사위 눈금에 따른 배율 설정
    var diceRoll = rollWeightedDie();
    switch (diceRoll) {
        case 1:
            return 3;
        case 2:
            return 5;
        case 3:
            return 8;
        case 4:
            return 12;
        case 5:
            return 15;
        case 6:
            return 50;
        default:
            return 1;
    }
}
// 가중치가 적용된 주사위 굴리기 함수
function rollWeightedDie() {
    // 확률에 따라 주사위 눈금 결정
    var probabilities = [0.8, 0.1, 0.05, 0.03, 0.015, 0.005]; // 각 눈금에 대한 확률
    var randomValue = Math.random();
    var cumulativeProbability = 0;
    for (var i = 0; i < probabilities.length; i++) {
        cumulativeProbability += probabilities[i];
        if (randomValue <= cumulativeProbability) {
            return i + 1;
        }
    }
    return 1;
}
