function getRandomEmojiFromType(types, petType) {
    const typeIndex = types.findIndex((type) => type.name === petType);
    if (typeIndex !== -1) {
        const emojis = types[typeIndex].emojis;
        return emojis[Math.floor(Math.random() * emojis.length)];
    }
    return null;
}
function difftypeBuff(r1user, r2user) {
    const types = ["하늘", "땅", "바다"];
    const advantage = {
        하늘: "땅",
        땅: "바다",
        바다: "하늘"
    };
    // 잘못된 타입이 들어오면 기본 버프 리턴
    if (!types.includes(r1user.pettype) || !types.includes(r2user.pettype)) {
        return {
            buff1: 1,
            buff2: 1
        };
    }
    if (r1user.pettype === r2user.pettype) {
        return {
            buff1: 1,
            buff2: 1
        };
    } else if (advantage[r1user.pettype] === r2user.pettype) {
        return {
            buff1: 1.3,
            buff2: 1
        };
    } else {
        return {
            buff1: 1,
            buff2: 1.3
        };
    }
}
function petgameplay(newexp1, newexp2, replier) {
    var result1 = newexp1;
    var result2 = newexp2;
    while (result1 > 0 && result2 > 0) {
        var user1Roll = Math.floor(Math.random() * 10) + 1;
        var user2Roll = Math.floor(Math.random() * 10) + 1;
        result1 -= user2Roll;
        result2 -= user1Roll;
    }
    if (result1 <= 0 && result1 < result2) {
        return {
            winner: 2,
            remainExp1: "기절",
            remainExp2: result2
        };
    } else if (result2 <= 0 && result2 < newexp1) {
        return {
            winner: 1,
            remainExp1: result1,
            remainExp2: "기절"
        };
    } else {
        return petgameplay(newexp1, newexp2);
    }
}
