/**
 * 301강 이상에서도 치명타 확률은 "동일"해야 하므로
 * 치확 계산에 사용하는 강화레벨은 300으로 캡
 */
function getCappedUpgradeForCrit(upgradeLevel) {
    var u = parseInt(upgradeLevel || 0, 10);
    if (u > 300) return 300;
    if (u < 0) return 0;
    return u;
}

/**
 * 펫의 강화 레벨에 따른 치명타 확률(%) 계산 함수
 * @param {number} upgradeLevel - 펫의 현재 강화 레벨
 * @returns {string} - 계산된 치명타 확률 (소수점 2자리, % 기호 제외)
 */
function getCritChance(upgradeLevel) {
    upgradeLevel = getCappedUpgradeForCrit(upgradeLevel);

    var critChance = 0;
    if (upgradeLevel <= 100) {
        critChance = upgradeLevel * 0.5;
    } else if (upgradeLevel <= 200) {
        critChance = 100 * 0.5 + (upgradeLevel - 100) * 0.3;
    } else {
        // <= 300
        critChance = 100 * 0.5 + 100 * 0.3 + (upgradeLevel - 200) * 0.1;
    }
    return critChance.toFixed(2);
}

/**
 * 치명타 확률을 0~1 범위(rate)로 반환
 * - 301강 이상은 300강 확률과 동일(캡)
 * @param {number} upgradeLevel
 * @returns {number} - 0.0 ~ 1.0
 */
function calculateCritChance(upgradeLevel) {
    var capped = getCappedUpgradeForCrit(upgradeLevel);
    var pctStr = getCritChance(capped); // "15.00" 같은 문자열
    var pct = parseFloat(pctStr);
    if (isNaN(pct)) pct = 0;

    var rate = pct / 100;
    if (rate > 1) rate = 1;
    if (rate < 0) rate = 0;
    return rate;
}

/**
 * 301강부터 치명타 배수(계수) 증가
 * 0~300강: 1.70 고정
 * 301강: 1.71, 302강: 1.72 ... (0.01씩 증가)
 * @param {number} upgradeLevel
 * @returns {number} - 배수(소수 2자리)
 */
function getCritMultiplier(upgradeLevel) {
    var u = parseInt(upgradeLevel || 0, 10);
    if (u <= 300) return BASE_CRIT_DAMAGE_MULTIPLIER; // 1.7

    var mul = BASE_CRIT_DAMAGE_MULTIPLIER + (u - 300) * 0.01;
    return parseFloat(mul.toFixed(2));
}

/**
 * 크리티컬 데미지 계산 함수
 * @param {object} petObj - 유저 펫 정보
 * @param {number} damage - 기본 데미지
 * @returns {number} - 크리티컬이 적용된 최종 데미지
 */
function calculateCriticalDamage(petObj, damage) {
    var upgradeLevel = (petObj && petObj.upgrade) || 0;
    var critChance = calculateCritChance(upgradeLevel);
    var isCritical = Math.random() < critChance;

    if (isCritical) {
        return Math.round(damage * getCritMultiplier(upgradeLevel)); //  301+ 배수 반영
    }
    return damage;
}

/**
 * 크리티컬 데미지 계산 함수
 * @param {object} pet - 펫 정보
 * @param {number} damage - 기본 데미지
 * @returns {number} - 크리티컬이 적용된 최종 데미지
 */
function calculateCriticalDamageWithPet(pet, damage) {
    var upgradeLevel = (pet && pet.upgrade) || 0;
    var critChance = calculateCritChance(upgradeLevel);
    var isCritical = Math.random() < critChance;

    if (isCritical) {
        return Math.round(damage * getCritMultiplier(upgradeLevel)); //  301+ 배수 반영
    }
    return damage;
}

