// 후원패스 명령어명으로 설정을 찾는 함수
function getSupportPassConfigByCommandName(commandName) {
    var configs = getSupportPassConfigs();
    for (var i = 0; i < configs.length; i++) {
        for (var j = 0; j < configs[i].commandNames.length; j++) {
            if (configs[i].commandNames[j] === commandName) return configs[i];
        }
    }
    return null;
}

// 후원패스 저장 구조를 보장하는 함수
function ensureSupportPassStore(data, user) {
    if (!data.member[user]) return null;
    var member = data.member[user];
    if (!member.pass || typeof member.pass !== "object") member.pass = {};
    return member.pass;
}

// 후원패스 날짜 문자열이 유효한지 확인하는 함수
function isValidSupportPassDateText(text) {
    return getSupportPassDateValue(text) !== null;
}

// 후원패스 날짜 문자열을 비교 가능한 값으로 변환하는 함수
function getSupportPassDateValue(text) {
    var match = String(text || "").match(/^(\d{2})\.(\d{2})\.(\d{2})$/);
    if (!match) return null;
    var year = 2000 + parseInt(match[1], 10);
    var month = parseInt(match[2], 10);
    var day = parseInt(match[3], 10);
    var date = new Date(Date.UTC(year, month - 1, day));
    if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) return null;
    return year * 10000 + month * 100 + day;
}

// 한국 시간의 오늘 날짜를 후원패스 비교값으로 반환하는 함수
function getTodaySupportPassDateValue() {
    var now = new Date(new Date().getTime() + 9 * 60 * 60 * 1000);
    var y = now.getUTCFullYear();
    var m = now.getUTCMonth() + 1;
    var d = now.getUTCDate();
    return y * 10000 + m * 100 + d;
}

// 후원패스가 현재 사용 가능한지 확인하는 함수
function isSupportPassActive(data, user, passKey) {
    var member = data.member && data.member[user] ? data.member[user] : null;
    var pass = member && member.pass && member.pass[passKey] ? member.pass[passKey] : null;
    if (!pass || pass.enabled !== true) {
        var configs = getSupportPassConfigs();
        for (var i = 0; i < configs.length; i++) {
            if (configs[i].key === passKey && configs[i].arrayName) {
                var legacyArr = data[configs[i].arrayName];
                return legacyArr instanceof Array && legacyArr.indexOf(user) !== -1;
            }
        }
        return false;
    }
    if (pass.permanent === true) return true;
    var expireValue = getSupportPassDateValue(pass.endDate);
    if (expireValue === null) return true;
    return expireValue >= getTodaySupportPassDateValue();
}

// 현재 사용 가능한 후원패스 유저 목록을 반환하는 함수
function getActiveSupportPassUsers(data, passKey) {
    var users = [];
    if (!data || !data.member) return users;
    for (var user in data.member) {
        if (isSupportPassActive(data, user, passKey)) users.push(user);
    }
    return users;
}

// 만료된 후원패스를 정리하고 자격이 끝난 자동탐험권을 회수하는 함수
function cleanupExpiredSupportPasses(data) {
    var result = { changed: false, expiredCount: 0, removedTicketCount: 0, invalidDateCount: 0 };
    if (!data || !data.member) return result;
    var configs = getSupportPassConfigs();
    var todayValue = getTodaySupportPassDateValue();
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var member = data.member[user];
        if (!member || !member.pass) continue;
        for (var i = 0; i < configs.length; i++) {
            var config = configs[i];
            var pass = member.pass[config.key];
            if (!pass || pass.enabled !== true || pass.permanent === true) continue;
            var expireValue = getSupportPassDateValue(pass.endDate);
            if (expireValue === null) {
                result.invalidDateCount++;
                debuggerLog("[후원패스 만료 정리] 잘못된 날짜로 자동 정리 제외: " + user + " / " + config.key + " / " + pass.endDate);
                continue;
            }
            if (expireValue >= todayValue) continue;
            pass.enabled = false;
            result.changed = true;
            result.expiredCount++;
            debuggerLog("[후원패스 만료 정리] 패스 만료: " + user + " / " + config.key + " / " + pass.endDate);
        }
        var hasManagedAutoPass = !!(member.pass.newbie || member.pass.hoi);
        if (hasManagedAutoPass && !isSupportPassActive(data, user, "newbie") && !isSupportPassActive(data, user, "hoi")) {
            var removedTicketCount = removeAllItem(data, user, "자동탐험권🌄");
            if (removedTicketCount > 0) {
                result.changed = true;
                result.removedTicketCount += removedTicketCount;
                debuggerLog("[후원패스 만료 정리] 자동탐험권 회수: " + user + " / " + removedTicketCount + "개");
            }
        }
    }
    return result;
}

// 자동탐험권 보유 자격이 없는 유저 목록을 반환하는 함수
function getInvalidAutoExploreTicketUsers(data) {
    var users = [];
    if (!data || !data.member) return users;
    for (var user in data.member) {
        if (!data.member.hasOwnProperty(user)) continue;
        var member = data.member[user];
        var ticketCount = member && member.bag ? parseInt(member.bag["자동탐험권🌄"], 10) || 0 : 0;
        if (ticketCount < 1) continue;
        if (isSupportPassActive(data, user, "newbie") || isSupportPassActive(data, user, "hoi")) continue;
        users.push({ user: user, count: ticketCount });
    }
    users.sort(function (a, b) {
        if (a.user < b.user) return -1;
        if (a.user > b.user) return 1;
        return 0;
    });
    return users;
}

// 후원패스 표시 문자열을 만드는 함수
function formatSupportPassStatus(data, user, config) {
    if (!isSupportPassActive(data, user, config.key)) return config.label + " 미사용중[❌]";
    var pass = data.member[user].pass && data.member[user].pass[config.key] ? data.member[user].pass[config.key] : null;
    if (!pass) return config.label + " 미사용중[❌]";
    if (pass.permanent === true) return config.label + " 영구권 사용중[✅]";
    return config.label + " " + pass.endDate + " 종료예정[✅]";
}

// 유저 패키지가방용 후원패스 표시 줄을 만드는 함수
function buildUserSupportPassLines(data, user) {
    var configs = getSupportPassConfigs();
    var lines = [];
    for (var i = 0; i < configs.length; i++) {
        lines.push(formatSupportPassStatus(data, user, configs[i]));
    }
    return lines;
}

// 전체 후원패스 목록 메시지를 만드는 함수
function buildSupportPassListMessage(data, petData, guildData) {
    var configs = getSupportPassConfigs();
    var lines = ["호월패스 전체목록 안내:", "[원데이패스, 초보패스, 호이패스, 길드공헌패스, 다이아패스] / " + allsee, ""];
    for (var i = 0; i < configs.length; i++) {
        var config = configs[i];
        var activeUsers = [];
        for (var user in data.member) {
            if (isSupportPassActive(data, user, config.key)) activeUsers.push(user);
        }
        activeUsers.sort(function (a, b) {
            var ap = data.member[a].pass && data.member[a].pass[config.key] ? data.member[a].pass[config.key] : { permanent: true };
            var bp = data.member[b].pass && data.member[b].pass[config.key] ? data.member[b].pass[config.key] : { permanent: true };
            if (ap.permanent && !bp.permanent) return 1;
            if (!ap.permanent && bp.permanent) return -1;
            return (getSupportPassDateValue(ap.endDate) || 99999999) - (getSupportPassDateValue(bp.endDate) || 99999999);
        });
        lines.push(config.label + " 명단");
        if (activeUsers.length < 1) {
            lines.push("미사용중[❌]");
        } else {
            for (var j = 0; j < activeUsers.length; j++) {
                var pass = data.member[activeUsers[j]].pass && data.member[activeUsers[j]].pass[config.key] ? data.member[activeUsers[j]].pass[config.key] : null;
                var endText = !pass ? "미사용중[❌]" : (pass.permanent ? "영구권 사용중[✅]" : pass.endDate + " 까지");
                lines.push("[" + checkRank(data, petData, guildData, activeUsers[j]) + "] " + endText);
            }
        }
        lines.push("━━━━━━━━━━━");
        lines.push("");
    }
    var invalidTicketUsers = getInvalidAutoExploreTicketUsers(data);
    lines.push("━━━━━━━━━━━━");
    if (invalidTicketUsers.length < 1) {
        lines.push("✅ 자동탐험권 정합성 검사");
        lines.push("삭제 대상 유저가 없습니다.");
    } else {
        lines.push("⚠️ 자동탐험권 수동 삭제해야하는 유저");
        lines.push("━━━━━━━━━━━━");
        lines.push("초보패스·호이패스 명단에는 없지만");
        lines.push("자동탐험권🌄을 보유 중인 유저입니다.");
        lines.push("");
        for (var invalidIndex = 0; invalidIndex < invalidTicketUsers.length; invalidIndex++) {
            var invalidTicketUser = invalidTicketUsers[invalidIndex];
            lines.push((invalidIndex + 1) + ". " + checkRank(data, petData, guildData, invalidTicketUser.user) + " — 자동탐험권🌄 x" + invalidTicketUser.count);
        }
        lines.push("");
        lines.push("총 " + invalidTicketUsers.length + "명");
    }
    return lines.join("\n");
}

// 후원패스 명령어의 대상과 옵션을 분석하는 함수
function parseSupportPassCommandMeta(msg) {
    var passMatch = String(msg || "").match(/^\/(원데이패스|공헌패스|초보패스|초보|호이패스|다이아패스)(추가|삭제),\s*([^]+)$/);
    if (!passMatch) return null;
    var passConfig = getSupportPassConfigByCommandName(passMatch[1]);
    if (!passConfig) return null;
    var action = passMatch[2];
    var body = String(passMatch[3] || "").trim();
    var tokens = body.split(/\s+/);
    var lastToken = tokens.length > 0 ? tokens[tokens.length - 1] : "";
    var option = action === "추가" && (lastToken === "영구권" || isValidSupportPassDateText(lastToken)) ? lastToken : "";
    var userIDText = action === "추가" && option ? tokens.slice(0, tokens.length - 1).join(" ") : body;
    return { config: passConfig, action: action, user: userIDText, option: option };
}

// 저장된 후원패스 상태를 확인하는 함수
function buildSupportPassSaveCheckMessage(msg, savedData) {
    var meta = parseSupportPassCommandMeta(msg);
    if (!meta || !savedData || !savedData.member || !savedData.member[meta.user]) return "\n⚠️ 저장확인: member.json에서 대상 유저를 확인하지 못했습니다.";
    var member = savedData.member[meta.user];
    var pass = member.pass && member.pass[meta.config.key] ? member.pass[meta.config.key] : null;
    if (meta.action === "추가") {
        if (!pass || pass.enabled !== true) return "\n⚠️ 저장확인: member.json에서 패스 저장을 확인하지 못했습니다.";
        var savedEndText = pass.permanent === true ? "영구권" : pass.endDate + "까지";
        var lines = ["\n저장확인: 패스 저장 완료 (" + savedEndText + ")"];
        if (meta.config.key === "newbie" || meta.config.key === "hoi") {
            var ticketCount = member.bag && member.bag["자동탐험권🌄"] ? member.bag["자동탐험권🌄"] : 0;
            lines.push("저장확인: 자동탐험권🌄 " + ticketCount + "개");
        }
        return lines.join("\n");
    }
    if (pass && pass.enabled === true) return "\n⚠️ 저장확인: member.json에서 패스 삭제를 확인하지 못했습니다.";
    var deleteLines = ["\n저장확인: 패스 삭제 저장 완료"];
    if (meta.config.key === "newbie" || meta.config.key === "hoi") {
        var remainingTicketCount = member.bag && member.bag["자동탐험권🌄"] ? member.bag["자동탐험권🌄"] : 0;
        if (!isSupportPassActive(savedData, meta.user, "newbie") && !isSupportPassActive(savedData, meta.user, "hoi")) {
            if (remainingTicketCount > 0) {
                deleteLines.push("⚠️ 저장확인: 자동탐험권🌄 " + remainingTicketCount + "개가 남아 있습니다.");
            } else {
                deleteLines.push("저장확인: 자동탐험권🌄 회수 완료");
            }
        } else {
            deleteLines.push("저장확인: 다른 자동탐험 패스가 유효하여 자동탐험권🌄 유지");
        }
    }
    return deleteLines.join("\n");
}

function processUserIDCommand(msg, data) {
    var passMeta = parseSupportPassCommandMeta(msg);
    if (!passMeta) return "알 수 없는 명령어입니다.";

    var passConfig = passMeta.config;
    if (!passConfig) return "알 수 없는 명령어입니다.";
    var action = passMeta.action;
    var option = passMeta.option;
    var userIDText = passMeta.user;
    if (!data.member || !data.member[userIDText]) return "❌ 해당 유저를 찾을 수 없습니다.";

    if (action === "추가") {
        if (!option) option = "영구권";
        if (option !== "영구권") {
            var expireValue = getSupportPassDateValue(option);
            if (expireValue !== null && expireValue < getTodaySupportPassDateValue()) {
                return "❌ 지난 날짜로 패스를 추가할 수 없습니다.\n오늘 이후 날짜를 입력해주세요.\n예) /호이패스추가, " + userIDText + " 26.06.21";
            }
        }
        var passStore = ensureSupportPassStore(data, userIDText);
        var beforeActive = passStore[passConfig.key] && passStore[passConfig.key].enabled === true;
        passStore[passConfig.key] = {
            enabled: true,
            endDate: option === "영구권" ? "" : option,
            permanent: option === "영구권"
        };
        var passEndText = option === "영구권" ? "영구권" : option + "까지";
        var addLines = [
            beforeActive ? "⚠️ 이미 해당 패스를 보유 중입니다.\n기존 종료일을 새 종료일로 갱신합니다." : userIDText + " 사용자에게 패스가 추가되었습니다.",
            "패스 기간: " + passEndText
        ];
        if (passConfig.key === "newbie" || passConfig.key === "hoi") {
            addItem(data, userIDText, "자동탐험권🌄", 1);
            addLines.push("자동탐험권🌄 1개가 지급되었습니다.");
        }
        return addLines.join("\n");
    }

    var userPassStore = ensureSupportPassStore(data, userIDText);
    if (!userPassStore[passConfig.key] || userPassStore[passConfig.key].enabled !== true) {
        return "❌ 해당 유저는 해당 패스를 보유하고 있지 않습니다.";
    }
    userPassStore[passConfig.key].enabled = false;
    var deleteLines = [userIDText + " 사용자의 패스가 삭제되었습니다."];
    if (passConfig.key === "newbie" || passConfig.key === "hoi") {
        if (!isSupportPassActive(data, userIDText, "newbie") && !isSupportPassActive(data, userIDText, "hoi")) {
            removeAllItem(data, userIDText, "자동탐험권🌄");
            deleteLines.push("자동탐험권🌄을 모두 회수했습니다.");
        } else {
            deleteLines.push("다른 자동탐험 패스가 유효하여 자동탐험권🌄을 유지합니다.");
        }
    }
    return deleteLines.join("\n");
}
//////////////////////////////////////////////////////////////////////
// 이 아래는 info.js와 같은 함수를 사용하므로 수정 시 싱크맞춰야합니다.//
//////////////////////////////////////////////////////////////////////
function runPetUpgradeOnce(sender, data, petData, guildData, petSkillData) {
    var user = data.member[sender];
    if (!petData[sender]) {
        return { ok: false, message: "펫이 없습니다.", costSpent: false };
    }
    if (!petData[sender].upgrade) petData[sender].upgrade = 0;

    var upgradeLevel = petData[sender].upgrade;
    var upgradeCost = upgradeLevel < 100 ? 20000000 : upgradeLevel < 200 ? 50000000 : 100000000;
    if (user.point < upgradeCost) {
        return {
            ok: false,
            message: "포인트가 부족합니다.\n현재 포인트: " + numberWithCommas(user.point) + "\n필요한 포인트: " + numberWithCommas(upgradeCost),
            costSpent: false
        };
    }

    var needItemCount = upgradeLevel + 1;
    if (!user.bag["펫 강화석⭐"] || user.bag["펫 강화석⭐"] < needItemCount) {
        return {
            ok: false,
            message: "펫 강화석⭐이 부족합니다.\n필요한 펫 강화석⭐: " + needItemCount + "개",
            costSpent: false
        };
    }

    function findBestPetBoostItem(bag) {
        var best = null,
            bestPct = 0;
        var re = /^펫강화확률UP🌟\((\d+(?:\.\d+)?)%\)$/;
        for (var k in bag) {
            if (!bag.hasOwnProperty(k)) continue;
            if (!bag[k] || bag[k] <= 0) continue;
            var m = k.match(re);
            if (m) {
                var pct = parseFloat(m[1]);
                if (!isNaN(pct) && pct > bestPct) {
                    bestPct = pct;
                    best = k;
                }
            }
        }
        return best
            ? {
                name: best,
                addPct: bestPct
            }
            : null;
    }

    var traitApplied = hasPetSkill(petSkillData, sender, "대머리 대장장이");
    var traitBonus = traitApplied ? 0.05 : 0.0;
    var baseProbNow = upgradeLevel < 100 ? 0.55 - upgradeLevel * 0.005 : 0.05;
    var boostEligible = baseProbNow + traitBonus < 1.0;
    var chosenBoost = boostEligible ? findBestPetBoostItem(user.bag) : null;
    var boostApplied = !!chosenBoost;
    var boostBonus = boostApplied ? chosenBoost.addPct / 100 : 0.0;

    var bonusLines = [];
    if (boostApplied) {
        removeItem(data, sender, chosenBoost.name, 1);
        var leftCntAfterUse = Math.max(0, user.bag[chosenBoost.name] || 0);
        bonusLines.push(chosenBoost.name + " 사용 (보유: " + leftCntAfterUse + "개)");
    }
    if (traitApplied) {
        bonusLines.push("대머리 대장장이📙 펫스킬을 적용 받았습니다(5%)");
    }
    var bonusText = bonusLines.join("\n");

    var currentProb = baseProbNow + boostBonus + traitBonus;
    if (currentProb > 1) currentProb = 1;
    var success = Math.random() < currentProb;

    addPoint(data, sender, -upgradeCost);

    if (success) {
        removeItem(data, sender, "펫 강화석⭐", needItemCount);
        petData[sender].upgrade++;
        petData[sender].upgradeDateTime = new Date();

        var newLv = petData[sender].upgrade;
        var newCritChance = getCritChance(newLv);
        var critMul = getPetUpgradeCritMul(newLv);
        var nextLevel = newLv + 1;
        var baseProbNext = nextLevel < 100 ? 0.55 - nextLevel * 0.005 : 0.05;
        var nextBoostEligible = baseProbNext + traitBonus < 1.0;
        var nextBestAfterUse = nextBoostEligible ? findBestPetBoostItem(user.bag) : null;
        var nextItemBonus = nextBestAfterUse ? nextBestAfterUse.addPct / 100 : 0.0;
        var nextProb = baseProbNext + nextItemBonus + traitBonus;
        if (nextProb > 1) nextProb = 1;

        var successMessage =
            "[" +
            newLv +
            "강⭐ 펫 강화성공]\n" +
            "[" +
            checkRank(data, petData, guildData, sender) +
            "] 님의 [" +
            petData[sender].petimg +
            petData[sender].petname +
            "]이(가)\n" +
            "강화에 성공하였습니다.\n" +
            "[강화 " +
            newLv +
            "⭐] [치명타 확률 " +
            newCritChance +
            "%] [" +
            critMul +
            "배]\n" +
            "현재 포인트: 🅟" +
            numberWithCommas(user.point) +
            "\n\n" +
            "다음 펫강화확률⭐️: " +
            (nextProb * 100).toFixed(2) +
            "%(⬆️)\n" +
            "남은 펫 강화석⭐️: " +
            numberWithCommas(user.bag["펫 강화석⭐"] || 0) +
            (bonusText ? "\n\n" + bonusText : "");

        return {
            ok: true,
            success: true,
            costSpent: true,
            stonePreservedByArtisan: false,
            message: successMessage
        };
    }

    var artisanBreathTriggered = false;
    if (hasPetSkill(petSkillData, sender, "장인의 숨결")) {
        artisanBreathTriggered = Math.random() < 0.07;
    }
    if (!artisanBreathTriggered) {
        removeItem(data, sender, "펫 강화석⭐", needItemCount);
    }

    var nextLevelFail = upgradeLevel;
    var baseProbNextFail = nextLevelFail < 100 ? 0.55 - nextLevelFail * 0.005 : 0.05;
    var nextBoostEligibleFail = baseProbNextFail + traitBonus < 1.0;
    var nextBestAfterUseFail = nextBoostEligibleFail ? findBestPetBoostItem(user.bag) : null;
    var nextItemBonusFail = nextBestAfterUseFail ? nextBestAfterUseFail.addPct / 100 : 0.0;
    var nextProbIfFail = baseProbNextFail + nextItemBonusFail + traitBonus;
    if (nextProbIfFail > 1) nextProbIfFail = 1;

    return {
        ok: true,
        success: false,
        costSpent: true,
        stonePreservedByArtisan: artisanBreathTriggered,
        message:
            "[" +
            petData[sender].upgrade +
            "강⭐ 펫 강화실패]\n" +
            (artisanBreathTriggered ? "장인의 숨결📙 [펫 강화석⭐]을 소모하지 않았습니다.\n" : "하,, 펫 강화석⭐이 소멸하였습니다...\n") +
            "[" +
            checkRank(data, petData, guildData, sender) +
            "] 님의 [" +
            petData[sender].petimg +
            petData[sender].petname +
            "] 이(가)\n" +
            "강화에 실패하였습니다." +
            "\n현재 포인트: 🅟" +
            numberWithCommas(user.point) +
            "\n\n현재 펫강화확률⭐️: " +
            (nextProbIfFail * 100).toFixed(2) +
            "%(⬆️)" +
            "\n남은 펫 강화석⭐️: " +
            numberWithCommas(user.bag["펫 강화석⭐"] || 0) +
            (bonusText ? "\n\n" + bonusText : "")
    };
}

function runRepeatPetUpgrade(sender, data, petData, guildData, petSkillData, count) {
    var results = [];
    var tryCount = parseInt(count, 10) || 1;
    var successCount = 0;
    var failCount = 0;
    var artisanSavedCount = 0;
    var stoppedEarly = false;
    var beforePetName = (petData[sender] && petData[sender].petimg ? petData[sender].petimg : "") + (petData[sender] && petData[sender].petname ? petData[sender].petname : "펫");
    var beforePetUpgrade = petData[sender] && petData[sender].upgrade ? petData[sender].upgrade : 0;

    for (var i = 0; i < tryCount; i++) {
        var result = runPetUpgradeOnce(sender, data, petData, guildData, petSkillData);
        if (!result.costSpent) {
            results.push(result.message);
            stoppedEarly = true;
            break;
        }

        if (result.success) {
            successCount++;
        } else {
            failCount++;
        }
        if (result.stonePreservedByArtisan) {
            artisanSavedCount++;
        }

        if (tryCount === 1) {
            results.push(result.message);
        } else {
            results.push("[" + (i + 1) + "회]\n" + result.message);
        }
    }

    if (tryCount === 1) {
        return results.join("\n");
    }

    var afterPetName = (petData[sender] && petData[sender].petimg ? petData[sender].petimg : "") + (petData[sender] && petData[sender].petname ? petData[sender].petname : "펫");
    var afterPetUpgrade = petData[sender] && petData[sender].upgrade ? petData[sender].upgrade : 0;
    var summary = "⭐️펫강화 연속시도⭐️\n\n";
    summary += "강화 전: " + beforePetName + " [+" + beforePetUpgrade + "]\n";
    summary += "강화 후: " + afterPetName + " [+" + afterPetUpgrade + "]\n\n";
    summary += "시도🔂: [" + results.length + "/" + tryCount + "회]\n";
    summary += "성공🅾️: [" + successCount + "회]\n";
    summary += "실패❌: [" + failCount + "회]";
    if (artisanSavedCount > 0) {
        summary += "\n장인의 숨결📙 발동: [" + artisanSavedCount + "회] (강화석 미소모)";
    }
    summary += "\n현재 포인트: 🅟" + numberWithCommas(data.member[sender].point);
    if (stoppedEarly) {
        summary += "\n중간 종료: 포인트 또는 재료가 부족합니다.";
    }
    summary += "\n(펫강화 기록 상세보기)" + allsee;
    return summary + "\n\n" + results.join("\n\n");
}

function getMiniUpgradeTargetInfo(sender, petData, idxParam) {
    if (!petData[sender]) petData[sender] = {};

    if (idxParam === null || typeof idxParam === "undefined") {
        if (!petData[sender].miniPet) {
            return {
                ok: false,
                message: "❌ 강화할 미니펫이 없습니다.\n/미니펫강화 또는 /미니펫강화 [미니펫가방번호]"
            };
        }
        return {
            ok: true,
            mini: petData[sender].miniPet,
            targetType: "equipped"
        };
    }

    var bagIndex = parseInt(idxParam, 10);
    if (isNaN(bagIndex) || bagIndex < 0) {
        return {
            ok: false,
            message: "❌ 올바른 가방 번호를 입력해주세요.\n/미니펫강화 [미니펫가방번호]"
        };
    }
    if (bagIndex === 0) {
        if (!petData[sender].miniPet) {
            return {
                ok: false,
                message: "❌ 강화할 미니펫이 없습니다.\n/미니펫강화 또는 /미니펫강화 [미니펫가방번호]"
            };
        }
        return {
            ok: true,
            mini: petData[sender].miniPet,
            targetType: "equipped"
        };
    }

    var mini = (petData[sender].miniPetBag || []).find(function (pet) {
        return pet.sortIndex === bagIndex;
    });
    if (!mini) {
        return {
            ok: false,
            message: "❌ 올바른 가방 번호입니다.\n/미니펫강화 [미니펫가방번호]"
        };
    }
    return {
        ok: true,
        mini: mini,
        targetType: "bag"
    };
}

function getMiniUpgradeStateText(mini) {
    if (!mini) return "미니펫 없음";
    var name = (mini.name || "") + (mini.emoji || "");
    var battleExp = numberWithCommas(Number(mini.battleExp || 0));
    var grade = mini.grade || "일반";
    var upgradeDisplay = getMiniPetUpgradeDisplay(mini);
    var text = name + "(+" + battleExp + "💕)[" + grade + "]";
    if (upgradeDisplay) {
        text += " +" + upgradeDisplay + "💫";
    }
    return text;
}

function runMiniPetUpgradeOnce(sender, data, petData, guildData, petSkillData, idxParam) {
    var user = data.member[sender];
    if (!user) {
        return { ok: false, success: false, costSpent: false, message: "❌ 유저 정보가 없습니다." };
    }

    var targetInfo = getMiniUpgradeTargetInfo(sender, petData, idxParam);
    if (!targetInfo.ok) {
        return { ok: false, success: false, costSpent: false, message: targetInfo.message };
    }

    var mini = targetInfo.mini;
    if (!mini.upgrade) mini.upgrade = 0;

    var curLv = mini.upgrade;
    var maxLv = isElite(mini) ? ELITE_MINIPET_MAX_LV : MINIPET_MAX_LV;
    if (curLv >= maxLv) {
        return {
            ok: false,
            success: false,
            costSpent: false,
            message: "해당 미니펫은 이미 최대 강화(+MAX💫)입니다."
        };
    }

    var targetLv = curLv + 1;
    var battleExp = mini.battleExp || 0;
    var upgradeItemName = "미니펫 강화석💫";
    var needItemCount = targetLv;
    var stoneOwned = user.bag[upgradeItemName] || 0;
    if (stoneOwned < needItemCount) {
        return {
            ok: false,
            success: false,
            costSpent: false,
            message: "❌ 미니펫 강화석💫이 부족합니다.\n필요 수량: " + needItemCount + "개(보유 :" + stoneOwned + "개)"
        };
    }

    var costPoint = MINI_COST[targetLv];
    if (user.point < costPoint) {
        return {
            ok: false,
            success: false,
            costSpent: false,
            message: "❌ 포인트가 부족합니다.\n현재 포인트: " + numberWithCommas(user.point) + "\n필요 포인트: " + numberWithCommas(costPoint)
        };
    }

    var baseProb = MINI_PROB[targetLv];
    var traitPct = hasPetSkill(petSkillData, sender, "개통령") ? 10 : 0;
    var traitAdd = traitPct / 100;
    var boostEligible = baseProb + traitAdd < 1.0;
    var boost = boostEligible ? findBestMiniBoostItem(user.bag) : null;
    var boostAdd = boost ? boost.addPct / 100 : 0.0;
    var currentProb = baseProb + traitAdd + boostAdd;
    if (currentProb > 1) currentProb = 1.0;
    var success = Math.random() < currentProb;

    addPoint(data, sender, -costPoint);
    removeItem(data, sender, upgradeItemName, needItemCount);

    var boostLine = "";
    if (boost) {
        removeItem(data, sender, boost.name, 1);
        var leftBoost = Math.max(0, user.bag[boost.name] || 0);
        boostLine = "\n\n" + boost.name + " 사용 (보유: " + leftBoost + "개)";
    }
    var traitLine = "";
    if (traitPct > 0) {
        traitLine = "\n" + (traitPct === 10 ? "개같은집념(" + traitPct + "%) 특성을 적용 받았습니다." : "강조하고반복하는소리로도노래를들려주는붴쑉(" + traitPct + "%) 특성을 적용 받았습니다.");
    }

    var stonesLeft = Math.max(0, user.bag[upgradeItemName] || 0);
    var nextLvAfter = success ? Math.min(maxLv, curLv + 1) : curLv;
    var nextTargetLv = Math.min(maxLv, nextLvAfter + 1);
    var nextProbLine = "";
    if (nextLvAfter < maxLv) {
        var baseNext = MINI_PROB[nextTargetLv];
        var nextBoostEligible = baseNext + traitAdd < 1.0;
        var nextBest = nextBoostEligible ? findBestMiniBoostItem(user.bag) : null;
        var nextBoostAdd = nextBest ? nextBest.addPct / 100 : 0.0;
        var nextEffective = baseNext + traitAdd + nextBoostAdd;
        if (nextEffective > 1) nextEffective = 1.0;
        nextProbLine = (success ? "다음 미니펫 강화확률🐹 : " : "현재 미니펫 강화확률🐹 : ") + (nextEffective * 100).toFixed(2) + "%(⬆️)";
    } else {
        nextProbLine = success ? "다음 미니펫 강화확률🐹 : MAX" : "현재 미니펫 강화확률🐹 : MAX";
    }

    var nickname = checkRank(data, petData, guildData, sender);
    var header = "[" + nickname + "] 님\n" + mini.name + (mini.emoji || "") + "(+" + numberWithCommas(battleExp) + "💕)[" + (mini.grade || "일반") + "]\n";

    if (success) {
        var gain = getCharmGainFor(mini, targetLv) || 0;
        var beforeBattle = Number(mini.battleExp) || 0;
        var beforeCastle = Number(mini.castleExp) || 0;
        var beforeRaid = Number(mini.raidExp) || 0;
        mini.upgrade = nextLvAfter;
        mini.battleExp = beforeBattle + gain;
        mini.castleExp = beforeCastle + gain;
        mini.raidExp = beforeRaid + gain;
        refreshMiniPetSortIndex(petData, sender, miniPetData.gradeTable);

        if (mini.upgrade == maxLv) {
            noticeMsg("[" + nickname + "] 님의 [" + mini.name + (mini.emoji || "") + "] 미니펫이 +MAX💫에 도달했습니다! 축하해주세요!");
        }

        return {
            ok: true,
            success: true,
            costSpent: true,
            message:
                "[" +
                nextLvAfter +
                "강💫 미니펫 강화성공]\n" +
                header +
                "미니펫 강화에 성공하셨습니다!!\n\n" +
                numberWithCommas(beforeBattle) +
                "+" +
                numberWithCommas(gain) +
                "💕➡️ " +
                numberWithCommas(mini.battleExp || 0) +
                "💕 매력이 증가합니다.\n\n현재 포인트: 🅟" +
                numberWithCommas(user.point || 0) +
                "\n" +
                nextProbLine +
                "\n남은 " +
                upgradeItemName +
                " : " +
                numberWithCommas(stonesLeft) +
                "개" +
                (boostLine || "") +
                (traitLine || "")
        };
    }

    return {
        ok: true,
        success: false,
        costSpent: true,
        message:
            "[" +
            nextLvAfter +
            "강💫 미니펫 강화실패]\n" +
            header +
            "강화에 실패했습니다.\n\n현재 포인트: 🅟" +
            numberWithCommas(user.point) +
            "\n" +
            nextProbLine +
            "\n남은 " +
            upgradeItemName +
            " : " +
            numberWithCommas(stonesLeft) +
            "개" +
            (boostLine || "") +
            (traitLine || "")
    };
}

function runRepeatMiniPetUpgrade(sender, data, petData, guildData, petSkillData, idxParam, count) {
    var tryCount = parseInt(count, 10) || 1;
    var targetInfo = getMiniUpgradeTargetInfo(sender, petData, idxParam);
    if (!targetInfo.ok) {
        return targetInfo.message;
    }

    var beforeState = getMiniUpgradeStateText(targetInfo.mini);
    var successCount = 0;
    var failCount = 0;
    var actualTryCount = 0;
    var stopReason = "";
    var resultLogs = [];

    for (var i = 0; i < tryCount; i++) {
        var result = runMiniPetUpgradeOnce(sender, data, petData, guildData, petSkillData, idxParam);
        if (!result.costSpent) {
            stopReason = result.message;
            break;
        }

        actualTryCount++;
        if (result.success) {
            successCount++;
        } else {
            failCount++;
        }
        resultLogs.push("[" + actualTryCount + "회]\n" + result.message);
    }

    if (tryCount === 1) {
        if (resultLogs.length > 0) {
            return resultLogs.join("\n");
        }
        return stopReason || "강화를 진행할 수 없습니다.";
    }

    if (actualTryCount === 0) {
        return stopReason || "강화를 진행할 수 없습니다.";
    }

    var afterTargetInfo = getMiniUpgradeTargetInfo(sender, petData, idxParam);
    var afterMini = afterTargetInfo.ok ? afterTargetInfo.mini : targetInfo.mini;
    var afterState = getMiniUpgradeStateText(afterMini);

    var summary = "💫미니펫강화 연속시도💫\n\n";
    summary += "강화 전: " + beforeState + "\n";
    summary += "강화 후: " + afterState + "\n\n";
    summary += "시도🔂: [" + actualTryCount + "/" + tryCount + "회]\n";
    summary += "성공🅾️: [" + successCount + "회]\n";
    summary += "실패❌: [" + failCount + "회]\n";
    summary += "현재 포인트: 🅟" + numberWithCommas(data.member[sender].point || 0);
    if (stopReason) {
        summary += "\n\n※ " + stopReason.split("\n")[0];
    }
    summary += "\n\n(미니펫강화 기록 상세보기)" + allsee;
    return summary + "\n\n" + resultLogs.join("\n\n");
}

function runRepeatUpgrade(type, petFieldName, memberName, data, petData, guildData, petSkillData, count) {
    var results = [];
    var tryCount = parseInt(count, 10) || 1;
    var successCount = 0;
    var failCount = 0;
    var artisanSavedCount = 0;
    var stoppedEarly = false;
    var beforeUpgradeObj =
        petData[memberName] && petData[memberName][petFieldName]
            ? {
                name: petData[memberName][petFieldName].name,
                grade: petData[memberName][petFieldName].grade,
                upgrade: petData[memberName][petFieldName].upgrade
            }
            : null;

    for (var i = 0; i < tryCount; i++) {
        var upgradeResult = upgradeItemInfo(type, memberName, data, petData, guildData, petSkillData);
        var pointCost = upgradeResult.pointCost;
        var itemCostName = upgradeResult.itemCostName;
        var itemCost = upgradeResult.itemCost;

        // [FIX] 재화 부족 등으로 시도 자체가 안 된 경우 — fail 카운트 제외하고 즉시 중단
        if (!pointCost && !itemCost) {
            results.push(upgradeResult.message);
            stoppedEarly = true;
            break;
        }

        if (pointCost) addPoint(data, memberName, -pointCost);
        if (upgradeResult.shouldConsumeItem !== false && itemCostName && itemCost) removeItem(data, memberName, itemCostName, itemCost);
        if (upgradeResult.boostItemUsedName) removeItem(data, memberName, upgradeResult.boostItemUsedName, 1);

        if (upgradeResult.successFlag) {
            petData[memberName][petFieldName] = upgradeResult.obj;
            successCount++;
        } else {
            failCount++;
        }
        if (upgradeResult.stonePreservedByArtisan) {
            artisanSavedCount++;
        }

        if (tryCount === 1) {
            results.push(upgradeResult.message);
        } else {
            results.push("[" + (i + 1) + "회]\n" + upgradeResult.message);
        }
    }

    if (tryCount === 1) {
        return results.join("\n");
    }

    var summary = "";
    if (type == "ring") {
        summary += "💍반지강화 연속시도💍\n\n";
    } else if (type == "elemental") {
        summary += "🥀정령강화 연속시도🥀\n\n";
    }
    var afterUpgradeObj = petData[memberName] && petData[memberName][petFieldName] ? petData[memberName][petFieldName] : null;
    if (beforeUpgradeObj) {
        summary += "강화 전: " + beforeUpgradeObj.name + " [" + beforeUpgradeObj.grade + "](+" + beforeUpgradeObj.upgrade + ")\n";
    }
    if (afterUpgradeObj) {
        summary += "강화 후: " + afterUpgradeObj.name + " [" + afterUpgradeObj.grade + "](+" + afterUpgradeObj.upgrade + ")\n\n";
    }
    summary += "시도🔂: [" + results.length + "/" + tryCount + "회]\n";
    summary += "성공🅾️: [" + successCount + "회]\n";
    summary += "실패❌: [" + failCount + "회]";
    if (artisanSavedCount > 0) {
        summary += "\n장인의 숨결📙 발동: [" + artisanSavedCount + "회] (강화석 미소모)";
    }
    summary += "\n현재 포인트: 🅟" + numberWithCommas(data.member[memberName].point);
    if (stoppedEarly) {
        summary += "\n중간 종료: 재화 또는 재료 부족가 부족합니다.";
    }
    summary += "\n(강화 기록 상세보기)" + allsee;

    return summary + "\n\n" + results.join("\n\n");
}
