// 미니펫 가방 정렬 함수
//정렬 기준: 매력 → 등급 → 이름
function sortMiniPetBag(bag, gradeTable) {
    let gradePriority = {};
    for (let i = 0; i < gradeTable.length; i++) {
        gradePriority[gradeTable[i].grade] = i;
    }
    bag.sort(function (a, b) {
        if ((b.battleExp || 0) !== (a.battleExp || 0)) return (b.battleExp || 0) - (a.battleExp || 0);
        let gradeA = gradePriority[a.grade] !== undefined ? gradePriority[a.grade] : -1;
        let gradeB = gradePriority[b.grade] !== undefined ? gradePriority[b.grade] : -1;
        if (gradeB !== gradeA) return gradeB - gradeA;
        return (a.name || "").localeCompare(b.name || "", "ko");
    });
    return bag;
}
// 전체 유저의 미니펫 매력 정보를 수집하여 랭킹을 생성하는 함수
function getMiniPetExpRanking(petData, data, guildData) {
    let ranking = [];
    for (let user in petData) {
        let totalExp = getTotalMinipetExp(user, petData);
        if (totalExp > 0) {
            ranking.push({
                user: user,
                exp: totalExp
            });
        }
    }
    ranking.sort(function (a, b) {
        if (b.exp !== a.exp) return b.exp - a.exp;
        return a.user.localeCompare(b.user, "ko");
    });
    let message = "🐹미니펫 총 매력도 순위🐹\n\n(장착+가방 상위 10 합산 매력)\n'/미니펫연금'을 적어보세요\n순위를 유지하면 매일 보상이 파파팍!\n\n당신의 최강 컬렉션을 완성해뿅🐹\n\n";
    for (let i = 0; i < ranking.length; i++) {
        if (i === 10 && typeof allsee !== "undefined") {
            message += allsee;
        }
        let r = ranking[i];
        let rankName = checkRank(data, petData, guildData, r.user);
        message += i + 1 + "위 [" + rankName + "] : " + numberWithCommas(r.exp) + "🐹\n";
        ranking[i].rank = i + 1;
        ranking[i].rankName = rankName;
    }
    return {
        message: message.trim(),
        ranking: ranking
    };
}
// 특정 사용자의 미니펫 총 경험치 랭킹을 반환하는 함수
function getMiniPetTotalExpRank(username, petData) {
    let ranking = [];
    for (let user in petData) {
        let totalExp = getTotalMinipetExp(user, petData); // 정렬+상위10 포함 로직 사용
        if (totalExp > 0) {
            ranking.push({
                user: user,
                exp: totalExp
            });
        }
    }
    ranking.sort(function (a, b) {
        if (b.exp !== a.exp) return b.exp - a.exp;
        return a.user.localeCompare(b.user, "ko");
    });
    for (let i = 0; i < ranking.length; i++) {
        if (ranking[i].user === username) return i + 1 + "등";
    }
    return "순위없음";
}
// 특정 사용자의 미니펫 총 경험치를 계산하는 함수
function getTotalMinipetExp(sender, petData) {
    if (!petData[sender]) return 0;
    let equipped = petData[sender].miniPet;
    let bag = sortMiniPetBag(petData[sender].miniPetBag || [], miniPetData.gradeTable);
    let totalExp = 0;
    // debuggerLog(JSON.stringify(petData[sender]));
    if (equipped && equipped.battleExp) {
        totalExp += equipped.battleExp;
    }
    for (let i = 0; i < bag.length && i < 5; i++) {
        totalExp += bag[i].battleExp || 0;
    }
    return totalExp;
}
function getMiniPetBattleRank(username, petData) {
    let ranking = [];
    for (let user in petData) {
        let battle = petData[user].miniPetBattle;
        if (battle && battle.win >= 50) {
            // 50승 이상만 포함
            ranking.push({
                user: user,
                win: battle.win,
                lose: battle.lose
            });
        }
    }
    // 정렬 : 승리 많은 순 → 패 적은 순 → 가나다
    ranking.sort((a, b) => {
        if (b.win !== a.win) return b.win - a.win;
        if (a.lose !== b.lose) return a.lose - b.lose;
        return a.user.localeCompare(b.user, "ko");
    });
    // 특정 유저 순위 찾기
    for (let i = 0; i < ranking.length; i++) {
        if (ranking[i].user === username) {
            return i + 1 + "등🏆";
        }
    }
    return "순위없음";
}
// 수수료율을 적용하여 최종 지급 포인트 계산
function applyFee(amount, RankFee) {
    if (amount >= GLOBAL_CONFIG.fee.highRateThreshold) {
        return Math.round(GLOBAL_CONFIG.fee.highRateThreshold * RankFee.LowFeeR + (amount - GLOBAL_CONFIG.fee.highRateThreshold) * RankFee.HighFeeR);
    } else {
        return Math.round(amount * RankFee.LowFeeR);
    }
}
// 봇의 묵찌빠 선택 로직
function getBotMukchiChoice() {
    let r = Math.random() * 100;
    if (r < 31) return "묵";
    else if (r < 62) return "찌";
    else if (r < 93) return "빠";
    else return "눈";
}
// 묵찌빠 승패 판단 함수
function judgeMukchiBba(bot, user) {
    if (bot === user) return "tie";
    if (bot === "눈") {
        return user === "눈" ? "win" : "lose";
    }
    const winMap = {
        묵: "찌",
        찌: "빠",
        빠: "묵",
        눈: "묵"
    };
    return winMap[user] === bot ? "win" : "lose";
}
// 자동도전권 처리 함수
function autoMukchiBbaBetting(data) {
    for (let username in data.member) {
        const member = data.member[username];
        const bag = member.bag || {};
        if (bag["묵찌빠🕹️자동도전권"] > 0) {
            // 이미 배팅했는지 확인
            let alreadyBetted = false;
            for (let key in data.hoiland) {
                if (Array.isArray(data.hoiland[key])) {
                    if (data.hoiland[key].some((entry) => entry.user === username)) {
                        alreadyBetted = true;
                        break;
                    }
                }
            }
            if (alreadyBetted) continue;
            const r = Math.random() * 100;
            let selected = r < 31 ? "묵" : r < 62 ? "찌" : r < 93 ? "빠" : "눈";
            data.hoiland.NA.push({
                user: username,
                amount: 10000000,
                choice: selected,
                auto: true
            });
        }
    }
}
