// 묵찌빠 기록 업데이트 함수
function updateMukchiBbaRecord(data, user, resultType, boxCount, tierBoxCount) {
    if (!data.member[user]) data.member[user] = {};
    if (!data.member[user].mukchiBba) {
        data.member[user].mukchiBba = {
            play: 0,
            win: 0,
            tie: 0,
            lose: 0,
            luckyBox: 0,
            tierBonusBox: 0
        };
    }
    var record = data.member[user].mukchiBba;
    record.play++;
    if (resultType === "win") record.win++;
    else if (resultType === "tie") record.tie++;
    else if (resultType === "lose") record.lose++;
    if (boxCount) record.luckyBox += boxCount;
    if (tierBoxCount) record.tierBonusBox += tierBoxCount;
}
