// 미니펫 가방에서 sortIndex로 특정 미니펫 찾기
function getMiniPetBySortIndex(bag, sortIndex) {
    if (!Array.isArray(bag)) return null;
    for (var i = 0; i < bag.length; i++) {
        if (parseInt(bag[i].sortIndex || 0, 10) === parseInt(sortIndex, 10)) return bag[i];
    }
    return null;
}

// 미니펫 가방에서 sortIndex 배열에 해당하는 미니펫 제거 (업그레이드용으로 여러 개 제거할 때 유용)
function removeMiniPetsFromBag(bag, sortIndexes) {
    if (!Array.isArray(bag) || !Array.isArray(sortIndexes)) return [];
    var removeMap = {};
    for (var i = 0; i < sortIndexes.length; i++) removeMap[parseInt(sortIndexes[i], 10)] = true;
    var removed = [];
    for (var j = bag.length - 1; j >= 0; j--) {
        var currentIndex = parseInt(bag[j].sortIndex || 0, 10);
        if (removeMap[currentIndex]) removed.push(bag.splice(j, 1)[0]);
    }
    removed.reverse();
    return removed;
}

// 펫강화 치명타 배수 계산 함수
function getPetUpgradeCritMul(upgrade) {
    var u = parseInt(upgrade || 0, 10);
    if (u <= 300) return 1.7;
    var mul = 1.7 + (u - 300) * 0.01;
    return parseFloat(mul.toFixed(2)); // 부동소수 오차 방지
}

/**
 * 스타터팩 세팅
 * - 펫강화 30강(= 1.7배 구간)
 * - 펫특성: 이세계 용사✨ㅈ
 * - 정령/미니펫/스윗홈 초기 지급
 * - 가구는 "가구가방"을 비워둔 채(혹은 기본 0개) 스윗홈 등급(+4평)로 처리
 */
function applyStarterPet(pet, user, petSkillData) {
    // 펫강화
    pet.upgrade = 90;
    pet.upgradeDateTime = new Date().toISOString(); // member_pet.json 예시와 동일 형태

    if (petSkillData) {
        addPetSkillToBag(petSkillData, user, "십원✨", 1);
    }

    // 정령(키 이름: elemental)
    pet.elemental = {
        upgrade: 80,
        name: "피닉스🐦‍🔥",
        grade: "정령왕"
    };
    // 펫매력
    pet.petexp = 35000;

    // 미니펫 가방
    if (!pet.miniPetBag) pet.miniPetBag = [];

    // 초보자전용미니펫 추가
    pet.miniPet = {
        name: "초보자전용미니펫",
        emoji: "🌱",
        grade: "희귀",
        price: 0,
        battleExp: 100000,
        castleExp: 100000,
        raidExp: 100000
    };
    return pet;
}

// 스타터팩: 펫홈 기본 지급(별도 homeData 저장 구조)
function applyStarterHome(homeData, userName) {
    // homeData[userName] 기본 구조 보장
    homeData = initSweetHomeUser(homeData, userName);

    var u = homeData[userName];
    if (!u) {
        // 방어
        homeData[userName] = {};
        u = homeData[userName];
    }

    u.houseName = "산이 보이는 텐트집🏕️";
    u.exp = 3510; // (+1940💕) → 네 UI에서 exp + furnitureExp로 totalExp 계산됨
    u.floor = 18; // [+10평]

    // 기타 필드들 안전 초기화(없어도 되지만 스타터팩에서 깔끔하게)
    u.likeCnt = u.likeCnt || 0;
    u.visitCnt = u.visitCnt || 0;

    return homeData;
}

/**
 * 종합매력 계산 (펫정보/시련의탑 등 공용)
 * - /펫정보에서 쓰던 계산식을 그대로 함수화
 * - homeData는 외부에서 넘겨주거나, 없으면 내부에서 로드
 *
 * @param {string} sender
 * @param {object} data
 * @param {object} petData
 * @param {object=} homeData  // 선택: 이미 로드된 homeData가 있으면 넘겨 중복 로드 방지
 * @returns {number} 종합매력(정수)
 */
function calculateTotalExp(sender, data, petData, homeData, petSkillData) {
    if (!petData || !petData[sender]) return 0;

    var petInfo = petData[sender];
    var homeData = homeData || loadJsonFile(homeDataFile);

    var totalCastle = calculateCastleExp(sender, data, petData, homeData, petSkillData) || 0;
    var totalRaid = calculateRaidExp(sender, data, petData, homeData, petSkillData) || 0;

    // 강화 매력 보너스 계산
    var upgradeBonus = (petInfo.upgrade || 0) * GLOBAL_CONFIG.pet.totalCharmPerUpgrade;

    var total = totalCastle + totalRaid + upgradeBonus;



    // 혹시 NaN 방지
    total = parseInt(total, 10);
    if (isNaN(total)) total = 0;

    return total;
}

// 종합매력 시간체크용 세부 계산 결과를 반환하는 함수
function buildTotalExpTimeCheckDetail(sender, data, petData, homeData, petSkillData) {
    var result = {
        total: 0,
        lines: []
    };
    if (!petData || !petData[sender]) return result;

    var petInfo = petData[sender];
    var bagItems = data && data.member && data.member[sender] && data.member[sender].bag ? data.member[sender].bag : null;
    var rows = [];

    function addRow(label, value, ms) {
        value = parseInt(value, 10);
        if (isNaN(value)) value = 0;
        rows.push({ label: label, value: value, ms: ms });
    }

    function measure(label, fn) {
        var start = Date.now();
        var value = fn();
        addRow(label, value, Date.now() - start);
        return value;
    }

    function calcSkillExp(homeDataForSkill) {
        var skillExp = 0;
        if (hasPetSkill(petSkillData, sender, "장미칼")) skillExp += 500000;
        if (hasPetSkill(petSkillData, sender, "청룡언월도")) skillExp += 1000000;
        if (hasPetSkill(petSkillData, sender, "창조림") && hasEquippedCreationMiniPet(petData, sender)) skillExp += 500000;
        if (hasPetSkill(petSkillData, sender, "로열 하우스")) {
            var royalLumiereCount = getPlacedFurnitureCountByGrade(homeDataForSkill, sender, "로열 루미에르");
            if (royalLumiereCount >= 10) skillExp += 150000;
        }
        return skillExp;
    }

    var castleItemExp = measure("캐슬-공격아이템", function () {
        return calculateCastleItem(sender, data) || 0;
    });
    var castleEquipmentExp = measure("캐슬-정령/반지/가방", function () {
        var itemInfo = calculateItemInfoAll(sender, data, petData) || { castleExp: 0 };
        return itemInfo.castleExp || 0;
    });
    var castlePetExp = measure("캐슬-펫", function () {
        return petInfo.petexp || 0;
    });
    var castleMiniPetExp = measure("캐슬-미니펫", function () {
        return (petInfo.miniPet && petInfo.miniPet.castleExp) || 0;
    });
    var castleHomeExp = measure("캐슬-홈/가구", function () {
        var homeExp = getHomeTotalExp(homeData, sender) || 0;
        if (hasPetSkill(petSkillData, sender, "인테리어 장인")) homeExp = Math.floor(homeExp * 1.1);
        return homeExp;
    });
    var castleIntimacyExp = measure("캐슬-친밀도", function () {
        return getIntimacyExpFromBag(bagItems);
    });
    var castleSkillExp = measure("캐슬-펫스킬", function () {
        return calcSkillExp(homeData);
    });
    var castleTotal = castleItemExp + castleEquipmentExp + castlePetExp + castleMiniPetExp + castleHomeExp + castleIntimacyExp + castleSkillExp;

    var raidEquipmentExp = measure("레이드-정령/반지/가방", function () {
        var itemInfo = calculateItemInfoAll(sender, data, petData) || { raidExp: 0 };
        return itemInfo.raidExp || 0;
    });
    var raidPetExp = measure("레이드-펫", function () {
        return petInfo.petexp || 0;
    });
    var raidMiniPetExp = measure("레이드-미니펫", function () {
        return (petInfo.miniPet && petInfo.miniPet.raidExp) || 0;
    });
    var raidHomeExp = measure("레이드-홈/가구", function () {
        var homeExp = getHomeTotalExp(homeData, sender) || 0;
        if (hasPetSkill(petSkillData, sender, "인테리어 장인")) homeExp = Math.floor(homeExp * 1.1);
        return homeExp;
    });
    var raidSkillExp = measure("레이드-펫스킬", function () {
        return calcSkillExp(homeData);
    });
    var raidTotal = raidEquipmentExp + raidPetExp + raidMiniPetExp + raidHomeExp + raidSkillExp;
    var upgradeBonus = measure("강화 보너스", function () {
        return (petInfo.upgrade || 0) * GLOBAL_CONFIG.pet.totalCharmPerUpgrade;
    });

    result.total = parseInt(castleTotal + raidTotal + upgradeBonus, 10);
    if (isNaN(result.total)) result.total = 0;
    result.lines.push("캐슬 합계: " + numberWithCommas(castleTotal) + "💕");
    result.lines.push("레이드 합계: " + numberWithCommas(raidTotal) + "💕");
    result.lines.push("강화 보너스: " + numberWithCommas(upgradeBonus) + "💕");
    result.lines.push("━━━━━━━━━━━━");
    var visibleDetailCount = 0;
    for (var i = 0; i < rows.length; i++) {
        if (rows[i].ms <= 0) continue;
        result.lines.push(rows[i].label + ": " + numberWithCommas(rows[i].value) + "💕 / " + rows[i].ms + "ms");
        visibleDetailCount++;
    }
    if (visibleDetailCount < 1) {
        result.lines.push("1ms 이상 걸린 세부 항목이 없습니다.");
    }
    return result;
}

