function rollGuildRaidBox() {
    var r = Math.random() * 100;
    var gain = {};
    if (r < 80) {
        gain["펫먹이🍼"] = 350;
    } else if (r < 90) {
        gain["땅문서📜"] = 2;
    } else if (r < 94) {
        gain["주간상자🌼"] = 1;
    } else if (r < 97) {
        gain["미니펫강화석패키지💫"] = 1;
    } else if (r < 99) {
        gain["미니펫뽑기🐹(/미니펫오픈)"] = 2000;
    } else {
        gain[GLOBAL_CONFIG.petSkill.bookItemName] = 1;
    }
    return {
        gainItems: gain,
        gainTextLines: []
    };
}

