// 보상 아이템 묶음을 가방에 반영하는 함수
function applyRewardGainItems(data, user, gainItems) {
    for (var itemName in gainItems) {
        if (!gainItems.hasOwnProperty(itemName)) continue;
        addItem(data, user, itemName, gainItems[itemName]);
    }
}

// 보상 아이템 묶음을 출력 문자열로 변환하는 함수
function formatRewardGainItems(gainItems) {
    var lines = [];
    for (var itemName in gainItems) {
        if (!gainItems.hasOwnProperty(itemName)) continue;
        lines.push(itemName + " x" + numberWithCommas(gainItems[itemName]));
    }
    return lines.length ? lines.join(", ") : "획득 없음";
}

// 다이아상자를 열어 다이아를 지급하는 함수
function runDiamondBoxOpen(sender, data, petData, guildData, currencyLogData, msg, replier) {
    if (!data || !data.member || !data.member[sender]) return;

    var cmdLabel = "/다이아상자오픈";
    var boxName = "다이아상자💎(/다이아상자오픈)";
    var nick = checkRank(data, petData, guildData, sender);
    var bag = data.member[sender].bag || (data.member[sender].bag = {});
    var have = bag[boxName] || 0;

    if (!hasItem(data, sender, boxName, 1)) {
        replier.reply("❌[" + nick + "] 오픈할 상자가 없습니다.\n(" + boxName + ")");
        return;
    }

    var want = parseOpenCountFromMsg(msg);
    var openCount = resolveOpenCount(have, want);
    if (openCount === -1) {
        replier.reply("사용법: " + cmdLabel + " 또는 " + cmdLabel + " 숫자\n예) " + cmdLabel + " 10");
        return;
    }

    removeItem(data, sender, boxName, openCount);
    addDiamond(data, currencyLogData, sender, openCount);
    var currentDiamond = data.member[sender].diamond || 0;
    var remainBox = bag[boxName] || 0;

    replier.reply("💎 다이아상자 오픈 💎\n[" + nick + "]\n━━━━━━━━━━━━\n🎁 사용: 다이아상자💎 " + numberWithCommas(openCount) + "개\n✨ 획득: 다이아💎 " + numberWithCommas(openCount) + "개\n━━━━━━━━━━━━\n💰 보유 다이아: " + numberWithCommas(currentDiamond) + "개\n📦 남은 상자: " + numberWithCommas(remainBox) + "개");
}

